Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
ipvs: fix NULL deref in ip_vs_add_service error path

When ip_vs_bind_scheduler() succeeds in ip_vs_add_service(), the local
variable sched is set to NULL.  If ip_vs_start_estimator() subsequently
fails, the out_err cleanup calls ip_vs_unbind_scheduler(svc, sched)
with sched == NULL.  ip_vs_unbind_scheduler() passes the cur_sched NULL
check (because svc->scheduler was set by the successful bind) but then
dereferences the NULL sched parameter at sched->done_service, causing a
kernel panic at offset 0x30 from NULL.

 Oops: general protection fault, [..] [#1] PREEMPT SMP KASAN NOPTI
 KASAN: null-ptr-deref in range [0x0000000000000030-0x0000000000000037]
 RIP: 0010:ip_vs_unbind_scheduler (net/netfilter/ipvs/ip_vs_sched.c:69)
 Call Trace:
  <TASK>
  ip_vs_add_service.isra.0 (net/netfilter/ipvs/ip_vs_ctl.c:1500)
  do_ip_vs_set_ctl (net/netfilter/ipvs/ip_vs_ctl.c:2809)
  nf_setsockopt (net/netfilter/nf_sockopt.c:102)
  [..]

Fix by simply not clearing the local sched variable after a successful
bind.  ip_vs_unbind_scheduler() already detects whether a scheduler is
installed via svc->scheduler, and keeping sched non-NULL ensures the
error path passes the correct pointer to both ip_vs_unbind_scheduler()
and ip_vs_scheduler_put().

While the bug is older, the problem popups in more recent kernels (6.2),
when the new error path is taken after the ip_vs_start_estimator() call.

Fixes: 705dd3444081 ("ipvs: use kthreads for stats estimation")
Reported-by: Xiang Mei <xmei5@asu.edu>
Signed-off-by: Weiming Shi <bestswngs@gmail.com>
Acked-by: Simon Horman <horms@kernel.org>
Acked-by: Julian Anastasov <ja@ssi.bg>
Signed-off-by: Florian Westphal <fw@strlen.de>

Here is the root cause:
In `ip_vs_add_service()`, after a successful `ip_vs_bind_scheduler()`, the local variable `sched` is set to NULL. If `ip_vs_start_estimator()` subsequently fails, the error path passes this NULL `sched` to `ip_vs_unbind_scheduler()`, which dereferences it (`sched->done_service`), causing a NULL pointer dereference. The unnecessary NULL assignment is the root cause.

Here is the patch:
  */
 static int
 ip_vs_add_service(struct netns_ipvs *ipvs, struct ip_vs_service_user_kern *u,
 		  struct ip_vs_service **svc_p)
 {
 	int ret = 0;
 	struct ip_vs_scheduler *sched = NULL;
 	struct ip_vs_pe *pe = NULL;
 	struct ip_vs_service *svc = NULL;
 	int ret_hooks = -1;

 	/* increase the module use count */
 	if (!ip_vs_use_count_inc())
 		return -ENOPROTOOPT;

 	/* Lookup the scheduler by 'u->sched_name' */
 	if (strcmp(u->sched_name, "none")) {
 		sched = ip_vs_scheduler_get(u->sched_name);
 		if (!sched) {
 			pr_info("Scheduler module ip_vs_%s not found\n",
 				u->sched_name);
 			ret = -ENOENT;
 			goto out_err;
 		}
 	}

 	if (u->pe_name && *u->pe_name) {
 		pe = ip_vs_pe_getbyname(u->pe_name);
 		if (pe == NULL) {
 			pr_info("persistence engine module ip_vs_pe_%s "
 				"not found\n", u->pe_name);
 			ret = -ENOENT;
 			goto out_err;
 		}
 	}

 #ifdef CONFIG_IP_VS_IPV6
 	if (u->af == AF_INET6) {
 		__u32 plen = (__force __u32) u->netmask;

 		if (plen < 1 || plen > 128) {
 			ret = -EINVAL;
 			goto out_err;
 		}

 		ret = nf_defrag_ipv6_enable(ipvs->net);
 		if (ret)
 			goto out_err;
 	}
 #endif

 	if ((u->af == AF_INET && !ipvs->num_services) ||
 	    (u->af == AF_INET6 && !ipvs->num_services6)) {
 		ret = ip_vs_register_hooks(ipvs, u->af);
 		if (ret < 0)
 			goto out_err;
 		ret_hooks = ret;
 	}

 	svc = kzalloc_obj(struct ip_vs_service);
 	if (svc == NULL) {
 		IP_VS_DBG(1, "%s(): no memory\n", __func__);
 		ret = -ENOMEM;
 		goto out_err;
 	}
 	ret = ip_vs_stats_init_alloc(&svc->stats);
 	if (ret < 0)
 		goto out_err;

 	/* I'm the first user of the service */
 	atomic_set(&svc->refcnt, 0);

 	svc->af = u->af;
 	svc->protocol = u->protocol;
 	ip_vs_addr_copy(svc->af, &svc->addr, &u->addr);
 	svc->port = u->port;
 	svc->fwmark = u->fwmark;
 	svc->flags = u->flags & ~IP_VS_SVC_F_HASHED;
 	svc->timeout = u->timeout * HZ;
 	svc->netmask = u->netmask;
 	svc->ipvs = ipvs;

 	INIT_LIST_HEAD(&svc->destinations);
 	spin_lock_init(&svc->sched_lock);

 	/* Bind the scheduler */
 	if (sched) {
 		ret = ip_vs_bind_scheduler(svc, sched);
 		if (ret)
 			goto out_err;
-		sched = NULL;
 	}

 	ret = ip_vs_start_estimator(ipvs, &svc->stats);
 	if (ret < 0)
 		goto out_err;

 	/* Update the virtual service counters */
 	if (svc->port == FTPPORT)
 		atomic_inc(&ipvs->ftpsvc_counter);
 	else if (svc->port == 0)
 		atomic_inc(&ipvs->nullsvc_counter);
 	if (pe && pe->conn_out)
 		atomic_inc(&ipvs->conn_out_counter);

 	/* Bind the ct retriever */
 	RCU_INIT_POINTER(svc->pe, pe);
 	pe = NULL;

 	/* Count only IPv4 services for old get/setsockopt interface */
 	if (svc->af == AF_INET)
 		ipvs->num_services++;
 	else if (svc->af == AF_INET6)
 		ipvs->num_services6++;

 	/* Hash the service into the service table */
 	ip_vs_svc_hash(svc);

 	*svc_p = svc;

 	if (!READ_ONCE(ipvs->enable)) {
 		/* Now there is a service - full throttle */
 		WRITE_ONCE(ipvs->enable, 1);

 		/* Start estimation for first time */
 		ip_vs_est_reload_start(ipvs);
 	}

 	return 0;


  out_err:
 	if (ret_hooks >= 0)
 		ip_vs_unregister_hooks(ipvs, u->af);
 	if (svc != NULL) {
 		ip_vs_unbind_scheduler(svc, sched);
 		ip_vs_service_free(svc);
 	}
 	ip_vs_scheduler_put(sched);
 	ip_vs_pe_put(pe);

 	/* decrease the module use count */
 	ip_vs_use_count_dec();

 	return ret;
 }



